CREATE TABLE IF NOT EXISTS managed_asset_photos(asset_id UUID NOT NULL REFERENCES managed_assets(id) ON DELETE CASCADE,side TEXT NOT NULL CHECK(side IN ('front','rear')),mime_type TEXT NOT NULL,content BYTEA NOT NULL CHECK(octet_length(content)<=5242880),version UUID NOT NULL,PRIMARY KEY(asset_id,side));
CREATE TABLE IF NOT EXISTS asset_rack_photos(rack_id UUID NOT NULL REFERENCES asset_racks(id) ON DELETE CASCADE,side TEXT NOT NULL CHECK(side IN ('front','rear')),mime_type TEXT NOT NULL,content BYTEA NOT NULL CHECK(octet_length(content)<=5242880),version UUID NOT NULL,PRIMARY KEY(rack_id,side))
